use vw_config_types::ui::DesktopLocale;
pub fn gateway(locale: DesktopLocale) -> &'static str {
    crate::app::i18n::I18n::new(locale).__("服务端网关配置说明\n\n一、监听与暴露\n- gateway.port / gateway.host 控制 HTTP gateway 的监听地址。\n- allow_public_bind 默认关闭，防止在无隧道/代理保护的情况下直接暴露公网。\n\n二、安全与 skey\n- auth_enabled 开启后，客户端需通过 Authorization: Bearer <skey> 访问受保护端点。\n- 新增 skey 时只填写名称和可选过期日期；原始 skey 自动生成且仅展示一次。\n- skeys 只保存 enabled、skey_hash、脱敏 skey、名称和过期时间，原始 skey 不会写入配置。\n- 单个 skey 可禁用；禁用后不会通过鉴权。\n- trust_forwarded_headers 仅应在可信反向代理后开启。\n\n三、限流与幂等\n- webhook_rate_limit_per_minute 控制 webhook 每分钟请求上限。\n- rate_limit_max_keys 控制内存中追踪的客户端 key 数量。\n- idempotency_ttl_secs / idempotency_max_keys 控制 webhook 幂等缓存行为。\n\n四、Node Control\n- node_control.enabled 打开实验性 node-control API。\n- node_control.auth_token 为额外共享令牌，客户端需通过 X-Node-Control-Token 传递。\n- node_control.allowed_node_ids 为空表示不显式限制；可使用 * 允许所有节点。\n\n五、推荐默认\n- host 使用 127.0.0.1。\n- auth_enabled 默认关闭；对外暴露前再开启并配置 skey。\n- allow_public_bind 保持关闭。\n- trust_forwarded_headers 仅在受控代理链路后启用。")
}
pub fn gateway_client(locale: DesktopLocale) -> &'static str {
    crate::app::i18n::I18n::new(locale).__("客户端网关配置说明\n\n一、作用\n- 这里配置桌面端发请求时要连接的 Gateway 地址、租户与认证信息。\n- 支持多个 Gateway 服务；当前选中的服务会成为 Desktop 的客户端请求目标。\n- 这些设置不会修改服务端网关的监听配置。\n\n二、字段含义\n1) host\n- 目标 Gateway 主机地址，默认 127.0.0.1。\n\n2) port\n- 目标 Gateway 端口，默认 14682。\n\n3) platform_id / company_id\n- 平台与公司租户 ID，默认 10000 / 100000000；不能为空。\n\n4) skey\n- 可选 skey。填写后会作为 Authorization: Bearer <skey> 发送给网关。\n\n三、示例\n{\n  \"gateway_client\": {\n    \"active_server_id\": \"local\",\n    \"servers\": [\n      {\n        \"id\": \"local\",\n        \"name\": \"本地网关\",\n        \"host\": \"127.0.0.1\",\n        \"port\": 14682,\n        \"platform_id\": \"10000\",\n        \"company_id\": \"100000000\",\n        \"skey\": \"\"\n      }\n    ],\n    \"host\": \"127.0.0.1\",\n    \"port\": 14682,\n    \"platform_id\": \"10000\",\n    \"company_id\": \"100000000\",\n    \"skey\": \"\"\n  }\n}\n")
}
